#!/usr/bin/env bash
# Container startup. Docker provides no systemd, so services are started explicitly.
set -euo pipefail

mkdir -p /run/sshd

# Lab public key (generated by lab.sh, mounted read-only) used by ZeroStressRiskAssess to log in as 'dev'.
# It is copied rather than linked so that ownership and permissions can be set correctly.
if [ -f /lab/authorized_keys ]; then
  install -d -m 700 -o dev -g dev /home/dev/.ssh
  install -m 600 -o dev -g dev /lab/authorized_keys /home/dev/.ssh/authorized_keys
fi

# Firewall (secure profile only): requires the NET_ADMIN capability, granted to that service alone.
if [ -f /etc/nftables.conf ] && command -v nft >/dev/null; then
  nft -f /etc/nftables.conf
fi

# FTP only if the profile installed it, in the background; sshd in the foreground keeps the container alive.
if command -v vsftpd >/dev/null && [ -f /etc/vsftpd.conf ]; then
  mkdir -p /var/run/vsftpd/empty
  vsftpd /etc/vsftpd.conf &
fi

exec /usr/sbin/sshd -D -e
